import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { PaperScene } from './scene';
import { direct, type DirectedState } from './director';

let scene: PaperScene | null = null;
let root: HTMLElement | null = null;
let lastState: DirectedState | null = null;

function createPage(container: HTMLElement): HTMLElement {
  const page = document.createElement('main');
  page.className = 'conservation-page';
  page.innerHTML = `
    <div class="environment-field" aria-hidden="true">
      <img class="environment-image environment-damaged" src="/creative-assets/r12-paper-restoration/paper-damaged-v1.png" alt="">
      <img class="environment-image environment-restored" src="/creative-assets/r12-paper-restoration/paper-restored-v1.png" alt="">
      <div class="environment-shade"></div>
      <div class="repair-focus"></div>
    </div>

    <header class="site-head" aria-label="工坊页首">
      <a class="wordmark" href="#opening" aria-label="纸本文献修复工坊首页">
        <span class="wordmark-mark" aria-hidden="true"></span>
        <span>纸本文献修复工坊</span>
      </a>
      <a class="quiet-link" href="#submit">委托修复</a>
    </header>

    <div class="chapter-rail" aria-label="修复过程导航">
      <a href="#opening"><span>01</span> 勘察</a>
      <a href="#fibres"><span>02</span> 理纤</a>
      <a href="#mending"><span>03</span> 补纸</a>
      <a href="#reading"><span>04</span> 复读</a>
    </div>

    <section class="story opening" id="opening" data-scene="opening">
      <div class="copy hero-copy">
        <p class="eyebrow">纸本文献修复 · 一页一案</p>
        <h1>让一页旧纸，<br>重新被读懂。</h1>
        <p class="lede">潮渍、断裂与漫漶并非终点。我们从纸张纤维开始，保存时间留下的证据，也恢复它被阅读的可能。</p>
        <a class="text-action" href="#fibres">沿裂缝进入修复过程 <span aria-hidden="true">↓</span></a>
      </div>
      <p class="scene-note">受潮卷曲 · 裂口失纤 · 墨迹漫漶</p>
    </section>

    <section class="story fibres" id="fibres" data-scene="fibres">
      <div class="copy process-copy">
        <p class="step">01 / 理纤</p>
        <h2>先辨认每一根<br>断开的方向</h2>
        <p>在放大观察下，凌乱纤维被逐根舒展、归位。修复不是覆盖损伤，而是理解原纸如何形成。</p>
        <dl class="evidence">
          <div><dt>观察</dt><dd>纤维走向与纸帘纹</dd></div>
          <div><dt>处理</dt><dd>局部润湿与柔性展平</dd></div>
        </dl>
      </div>
    </section>

    <section class="story mending" id="mending" data-scene="mending">
      <div class="copy process-copy right-copy">
        <p class="step">02 / 手工补纸</p>
        <h2>补上缺失，<br>不抹去时间</h2>
        <p>选择纤维、厚度与色泽相近的手工纸，让毛边沿原裂口自然嵌合。补口可辨，却不抢夺原件的声音。</p>
        <p class="material-label">相近纤维 / 可逆黏合 / 湿润压合</p>
      </div>
    </section>

    <section class="story reading" id="reading" data-scene="reading">
      <div class="copy process-copy">
        <p class="step">03 / 墨迹复读</p>
        <h2>不是添写，<br>是让原迹重现</h2>
        <p>纸面平复、纤维稳定后，光线重新穿过墨与纸的层次。模糊的字迹恢复可辨，原始信息仍保持克制而诚实。</p>
        <blockquote>“修复的尺度，是让文献继续说自己的话。”</blockquote>
      </div>
    </section>

    <section class="story resolution" id="submit" data-scene="resolution">
      <div class="final-copy">
        <p class="eyebrow">私人收藏 · 小型档案机构</p>
        <h2>从这一页，开始保存。</h2>
        <p>上传纸页正反面照片并说明尺寸、损伤与保存环境，我们会先给出一份初步修复判断。</p>
        <a class="primary-action" href="mailto:studio@example.invalid?subject=纸本文献修复咨询">提交一页待修复文献 <span aria-hidden="true">↗</span></a>
        <p class="fine-print">初步判断不改变原件 · 正式处理前确认方案与可逆性</p>
      </div>
      <footer><span>纸本文献修复工坊</span><span>以最少干预，延长真实寿命</span></footer>
    </section>
  `;
  container.appendChild(page);
  return page;
}

startExperience(defineExperience({
  mount(context) {
    root = createPage(context.container);
    scene = new PaperScene(context.canvas, context.quality, context.viewport, context.reducedMotion);
  },
  update(frame) {
    if (!scene || !root) return;
    lastState = direct(frame.progress, frame.pointer, frame.elapsed, frame.reducedMotion);
    scene.render(lastState, frame.delta);
    root.style.setProperty('--story-progress', frame.progress.toFixed(4));
    root.style.setProperty('--restore-blend', lastState.restoredPage.toFixed(4));
    root.style.setProperty('--detail-blend', Math.min(1, lastState.fibreDepth * 1.15).toFixed(4));
    root.style.setProperty('--inspection-x', lastState.inspectionX.toFixed(4));
    root.style.setProperty('--inspection-y', lastState.inspectionY.toFixed(4));
    root.dataset.phase = lastState.phase;
  },
  resize(viewport) {
    scene?.resize(viewport);
  },
  dispose() {
    scene?.dispose();
    scene = null;
    lastState = null;
    root?.remove();
    root = null;
  }
}));

export type PointerState = Readonly<{ x: number; y: number }>;

export type DirectedState = Readonly<{
  phase: 'survey' | 'descent' | 'align' | 'mend' | 'read' | 'resolve';
  cameraZ: number;
  cameraY: number;
  cameraTilt: number;
  paperScale: number;
  damage: number;
  fibreDepth: number;
  fibreAlignment: number;
  patchFit: number;
  inkLegibility: number;
  restoredPage: number;
  inspectionX: number;
  inspectionY: number;
  lightWarmth: number;
}>;

const clamp01 = (value: number): number => Math.max(0, Math.min(1, value));
const smooth = (a: number, b: number, value: number): number => {
  const t = clamp01((value - a) / Math.max(0.0001, b - a));
  return t * t * (3 - 2 * t);
};
const mix = (a: number, b: number, t: number): number => a + (b - a) * t;

export function direct(progress: number, pointer: PointerState, elapsed: number, reducedMotion: boolean): DirectedState {
  const p = clamp01(progress);
  const descend = smooth(0.12, 0.34, p);
  const align = smooth(0.30, 0.51, p);
  const mend = smooth(0.52, 0.70, p);
  const read = smooth(0.69, 0.84, p);
  const resolve = smooth(0.84, 0.96, p);
  const returnToTable = resolve;
  const pointerWeight = reducedMotion ? 0 : 0.035 * (1 - resolve);
  const breath = reducedMotion ? 0 : Math.sin(elapsed * 0.28) * 0.015 * (1 - resolve);

  let phase: DirectedState['phase'] = 'survey';
  if (p >= 0.16) phase = 'descent';
  if (p >= 0.34) phase = 'align';
  if (p >= 0.54) phase = 'mend';
  if (p >= 0.71) phase = 'read';
  if (p >= 0.88) phase = 'resolve';

  return {
    phase,
    cameraZ: mix(7.4, 2.2, descend) + mix(0, 5.5, returnToTable),
    cameraY: mix(0.25, -0.85, descend) + mix(0, 1.05, returnToTable),
    cameraTilt: mix(-0.08, -0.42, descend) + mix(0, 0.47, returnToTable),
    paperScale: mix(1, 1.48, descend) + mix(0, -0.42, returnToTable),
    damage: 1 - smooth(0.58, 0.88, p),
    fibreDepth: descend * (1 - smooth(0.72, 0.91, p)),
    fibreAlignment: align,
    patchFit: mend,
    inkLegibility: read,
    restoredPage: resolve,
    inspectionX: pointer.x * pointerWeight,
    inspectionY: pointer.y * pointerWeight + breath,
    lightWarmth: mix(0.35, 1, resolve)
  };
}

import * as THREE from 'three';
import type { DirectedState } from './director';

export type SceneViewport = Readonly<{ width: number; height: number; dpr: number }>;
type Quality = 'low' | 'balanced' | 'high';

type Fibre = Readonly<{
  line: THREE.Line<THREE.BufferGeometry, THREE.LineBasicMaterial>;
  scattered: THREE.Vector3;
  aligned: THREE.Vector3;
}>;

const ease = (value: number): number => {
  const t = THREE.MathUtils.clamp(value, 0, 1);
  return t * t * (3 - 2 * t);
};

export class PaperScene {
  private readonly renderer: THREE.WebGLRenderer;
  private readonly scene = new THREE.Scene();
  private readonly camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.01, 10);
  private readonly fibreField = new THREE.Group();
  private readonly seam: THREE.Line<THREE.BufferGeometry, THREE.LineBasicMaterial>;
  private readonly fibres: Fibre[] = [];
  private readonly geometries: THREE.BufferGeometry[] = [];
  private readonly reducedMotion: boolean;
  private readonly lowQuality: boolean;

  constructor(canvas: HTMLCanvasElement, quality: Quality, viewport: SceneViewport, reducedMotion: boolean) {
    this.lowQuality = quality === 'low';
    this.reducedMotion = reducedMotion;
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: quality !== 'low',
      powerPreference: quality === 'high' ? 'high-performance' : 'default'
    });
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.setClearColor(0x000000, 0);
    this.camera.position.z = 2;
    this.scene.add(this.fibreField);

    this.createFibres(quality === 'high' ? 34 : quality === 'balanced' ? 24 : 14);
    const seamGeometry = new THREE.BufferGeometry().setFromPoints(
      new THREE.CatmullRomCurve3([
        new THREE.Vector3(0.32, 0.62, 0),
        new THREE.Vector3(0.24, 0.28, 0),
        new THREE.Vector3(0.08, -0.02, 0),
        new THREE.Vector3(0.16, -0.34, 0),
        new THREE.Vector3(0.03, -0.68, 0)
      ]).getPoints(48)
    );
    this.geometries.push(seamGeometry);
    this.seam = new THREE.Line(seamGeometry, new THREE.LineBasicMaterial({
      color: 0xe3c895,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    }));
    this.scene.add(this.seam);
    this.resize(viewport);
  }

  private createFibres(count: number): void {
    for (let index = 0; index < count; index += 1) {
      const side = index % 2 === 0 ? -1 : 1;
      const along = index / Math.max(1, count - 1);
      const anchorY = 0.66 - along * 1.34;
      const wave = Math.sin(index * 2.17) * 0.025;
      const points: THREE.Vector3[] = [];
      for (let point = 0; point <= 12; point += 1) {
        const t = point / 12;
        const x = 0.17 + side * t * (0.18 + (index % 5) * 0.017);
        const y = anchorY + Math.sin(t * Math.PI * 1.4 + index * 0.31) * (0.018 + along * 0.012);
        points.push(new THREE.Vector3(x, y, 0));
      }
      const geometry = new THREE.BufferGeometry().setFromPoints(points);
      this.geometries.push(geometry);
      const material = new THREE.LineBasicMaterial({
        color: index % 6 === 0 ? 0xd4aa6b : 0xe3d4b5,
        transparent: true,
        opacity: 0,
        depthWrite: false
      });
      const line = new THREE.Line(geometry, material);
      const scattered = new THREE.Vector3(side * (0.09 + (index % 4) * 0.018), wave * 4, 0);
      const aligned = new THREE.Vector3(side * 0.012, 0, 0);
      line.position.copy(scattered);
      this.fibreField.add(line);
      this.fibres.push({ line, scattered, aligned });
    }
  }

  render(state: DirectedState, delta: number): void {
    const settle = this.reducedMotion ? 1 : Math.min(1, Math.max(0.08, delta * 7));
    const detail = ease(state.fibreDepth) * (1 - ease(state.restoredPage));
    const alignment = ease(state.fibreAlignment);
    this.fibreField.scale.setScalar(THREE.MathUtils.lerp(this.fibreField.scale.x, 1 + detail * 0.18, settle));
    this.fibreField.position.x = THREE.MathUtils.lerp(this.fibreField.position.x, state.inspectionX * 0.35, settle);
    this.fibreField.position.y = THREE.MathUtils.lerp(this.fibreField.position.y, -state.inspectionY * 0.24, settle);

    this.fibres.forEach((fibre, index) => {
      const target = new THREE.Vector3().lerpVectors(fibre.scattered, fibre.aligned, alignment);
      fibre.line.position.lerp(target, settle);
      fibre.line.material.opacity = detail * (0.2 + (index % 5) * 0.035);
    });

    const seamPresence = ease(state.patchFit) * (1 - ease(state.restoredPage));
    this.seam.material.opacity = seamPresence * 0.58;
    this.seam.scale.x = THREE.MathUtils.lerp(1.07, 0.96, ease(state.patchFit));
    this.renderer.render(this.scene, this.camera);
  }

  resize(viewport: SceneViewport): void {
    const width = Math.max(1, viewport.width);
    const height = Math.max(1, viewport.height);
    this.renderer.setPixelRatio(Math.min(viewport.dpr, this.lowQuality ? 1.1 : 1.7));
    this.renderer.setSize(width, height, false);
    const aspect = width / height;
    this.camera.left = -aspect;
    this.camera.right = aspect;
    this.camera.top = 1;
    this.camera.bottom = -1;
    this.camera.updateProjectionMatrix();
  }

  dispose(): void {
    for (const fibre of this.fibres) fibre.line.material.dispose();
    this.seam.material.dispose();
    for (const geometry of this.geometries) geometry.dispose();
    this.renderer.dispose();
  }
}

:root {
  color-scheme: dark;
  --paper-light: #f2e7d2;
  --umber: #c89556;
  --deep: #17110c;
  --line: rgba(238, 220, 190, 0.22);
  --restore-blend: 0;
  --detail-blend: 0;
  --inspection-x: 0;
  --inspection-y: 0;
}

* { box-sizing: border-box; }
html { margin: 0; scroll-behavior: smooth; background: var(--deep); overflow-x: clip; }
body { margin: 0; width: 100%; min-width: 0; background: var(--deep); color: var(--paper-light); overflow-x: clip; font-family: "Noto Serif SC", "Songti SC", "STSong", serif; }
canvas { position: fixed; inset: 0; width: 100%; height: 100%; z-index: 2; pointer-events: none; }

.conservation-page { position: relative; z-index: 1; width: 100%; overflow: clip; }
.environment-field { position: fixed; inset: 0; z-index: 0; overflow: hidden; background: #17110c; pointer-events: none; }
.environment-image { position: absolute; inset: -2%; width: 104%; height: 104%; object-fit: cover; object-position: 53% 50%; filter: saturate(.82) contrast(1.03); transform: translate3d(calc(var(--inspection-x) * -10px), calc(var(--inspection-y) * 8px), 0) scale(calc(1.035 + var(--detail-blend) * .075)); transform-origin: 55% 52%; will-change: opacity, transform; }
.environment-damaged { opacity: calc(1 - var(--restore-blend)); }
.environment-restored { opacity: var(--restore-blend); }
.environment-shade { position: absolute; inset: 0; background: linear-gradient(90deg, rgba(14,10,7,.9) 0%, rgba(14,10,7,.56) 26%, rgba(14,10,7,.08) 57%, rgba(14,10,7,.28) 100%), linear-gradient(180deg, rgba(11,8,6,.25), transparent 38%, rgba(11,8,6,.38)); }
.repair-focus { position: absolute; inset: 0; opacity: var(--detail-blend); background: radial-gradient(ellipse at 58% 58%, transparent 0 16%, rgba(19,12,7,.12) 38%, rgba(10,7,5,.76) 82%); }

.site-head { position: fixed; z-index: 10; inset: 0 0 auto; display: flex; align-items: center; justify-content: space-between; padding: 24px clamp(20px, 4vw, 64px); font: 600 12px/1.4 system-ui, sans-serif; letter-spacing: .15em; }
.wordmark, .quiet-link { color: var(--paper-light); text-decoration: none; }
.wordmark { display: flex; align-items: center; gap: 11px; }
.wordmark-mark { width: 15px; height: 20px; border: 1px solid currentColor; transform: rotate(-3deg); opacity: .72; }
.quiet-link { border-bottom: 1px solid rgba(238,228,208,.48); padding-bottom: 5px; }

.chapter-rail { position: fixed; z-index: 8; right: clamp(16px, 2.7vw, 44px); top: 50%; transform: translateY(-50%); display: grid; gap: 14px; font: 10px/1.3 system-ui, sans-serif; letter-spacing: .12em; }
.chapter-rail a { color: rgba(242,231,210,.58); text-decoration: none; writing-mode: vertical-rl; }
.chapter-rail span { color: var(--umber); }

.story { position: relative; z-index: 3; min-height: 108svh; width: 100%; display: flex; align-items: center; padding: 14svh clamp(24px, 7vw, 112px); }
.opening { min-height: 112svh; align-items: flex-start; padding-top: 18svh; }
.copy { position: relative; width: min(520px, 45vw); }
.hero-copy { width: min(610px, 48vw); text-shadow: 0 2px 20px rgba(10,7,5,.35); }
.eyebrow, .step { margin: 0 0 20px; color: #d0a367; font: 600 11px/1.5 system-ui, sans-serif; letter-spacing: .22em; text-transform: uppercase; }
h1, h2, p { max-width: 100%; }
h1 { margin: 0; max-width: 9em; font-weight: 500; font-size: clamp(48px, 6.2vw, 88px); line-height: 1.03; letter-spacing: -.045em; text-wrap: balance; }
.lede { width: min(455px, 100%); margin: 26px 0 22px; color: rgba(242,231,210,.82); font-size: clamp(15px, 1.12vw, 18px); line-height: 1.8; }
.text-action { display: inline-flex; gap: 12px; align-items: center; color: var(--paper-light); text-decoration: none; font: 600 12px/1.4 system-ui, sans-serif; letter-spacing: .08em; border-bottom: 1px solid rgba(238,228,208,.4); padding: 8px 0; }
.scene-note { position: absolute; right: clamp(70px, 8vw, 132px); bottom: 11svh; margin: 0; color: rgba(242,231,210,.62); font: 10px/1.5 system-ui, sans-serif; letter-spacing: .14em; }

.process-copy { width: min(540px, 46vw); padding: clamp(28px, 3.5vw, 48px); background: linear-gradient(100deg, rgba(28,20,14,.9), rgba(28,20,14,.62) 72%, rgba(28,20,14,.12)); border-left: 1px solid var(--line); box-shadow: 0 28px 80px rgba(8,6,4,.16); backdrop-filter: blur(6px); }
.right-copy { margin-left: auto; margin-right: 5vw; background: linear-gradient(260deg, rgba(28,20,14,.92), rgba(28,20,14,.64) 72%, rgba(28,20,14,.12)); border-left: 0; border-right: 1px solid var(--line); }
h2 { margin: 0 0 22px; color: var(--paper-light); font-weight: 500; font-size: clamp(34px, 3.9vw, 58px); line-height: 1.12; letter-spacing: -.035em; text-wrap: balance; }
.process-copy > p:not(.step):not(.material-label) { margin: 0; max-width: 430px; color: rgba(242,231,210,.78); font-size: 16px; line-height: 1.85; }
.evidence { display: grid; grid-template-columns: 1fr 1fr; gap: 22px; margin: 26px 0 0; padding-top: 20px; border-top: 1px solid var(--line); }
.evidence div { display: grid; gap: 5px; }
.evidence dt { color: #d0a367; font: 11px/1.4 system-ui, sans-serif; letter-spacing: .15em; }
.evidence dd { margin: 0; color: var(--paper-light); font-size: 14px; }
.material-label { margin: 24px 0 0 !important; color: #d0a367 !important; font: 11px/1.6 system-ui, sans-serif !important; letter-spacing: .12em; }
blockquote { margin: 30px 0 0; padding: 17px 0 17px 22px; border-left: 1px solid #b57c43; color: var(--paper-light); font-size: 18px; line-height: 1.7; }

.resolution { min-height: 120svh; align-items: flex-end; justify-content: center; padding-bottom: 14svh; background: linear-gradient(180deg, transparent 10%, rgba(16,11,8,.1) 36%, rgba(16,11,8,.76) 100%); }
.final-copy { position: relative; width: min(700px, 90vw); padding: 44px clamp(28px, 5vw, 68px); text-align: center; background: rgba(28,20,14,.76); border-top: 1px solid rgba(238,220,190,.3); backdrop-filter: blur(9px); }
.final-copy h2 { font-size: clamp(38px, 4.8vw, 68px); }
.final-copy > p:not(.eyebrow):not(.fine-print) { margin: 0 auto 28px; width: min(550px, 100%); color: rgba(242,231,210,.78); font-size: 16px; line-height: 1.8; }
.primary-action { display: inline-flex; align-items: center; justify-content: center; gap: 24px; min-height: 58px; padding: 16px 24px; color: #23180f; background: #d9b37b; text-decoration: none; font: 700 15px/1.4 system-ui, sans-serif; letter-spacing: .05em; transition: background-color .25s ease, transform .25s ease; }
.primary-action:hover { background: #e8c998; transform: translateY(-2px); }
.fine-print { margin: 18px 0 0 !important; color: rgba(242,231,210,.5) !important; font: 11px/1.6 system-ui, sans-serif !important; letter-spacing: .06em; }
footer { position: absolute; bottom: 26px; left: clamp(20px, 4vw, 64px); right: clamp(20px, 4vw, 64px); display: flex; justify-content: space-between; padding-top: 15px; border-top: 1px solid var(--line); color: rgba(242,231,210,.45); font: 10px/1.4 system-ui, sans-serif; letter-spacing: .08em; }

@media (max-width: 720px) {
  .site-head { padding: 18px 20px; font-size: 10px; }
  .quiet-link, .chapter-rail { display: none; }
  .environment-image { inset: -1%; width: 102%; height: 102%; object-position: 61% 50%; transform: scale(calc(1.03 + var(--detail-blend) * .05)); }
  .environment-shade { background: linear-gradient(180deg, rgba(12,8,6,.76) 0%, rgba(12,8,6,.36) 42%, rgba(12,8,6,.82) 100%); }
  .story { min-height: 112svh; align-items: flex-end; padding: 15svh 20px 12svh; }
  .opening { min-height: 116svh; align-items: flex-start; padding-top: 15svh; }
  .copy, .hero-copy, .process-copy { width: 100%; }
  h1 { max-width: 8em; font-size: clamp(42px, 13vw, 60px); line-height: 1.06; }
  .lede { width: 100%; margin-top: 18px; font-size: 15px; line-height: 1.65; }
  .scene-note { right: 20px; bottom: 7svh; max-width: 68%; text-align: right; }
  .process-copy, .right-copy { margin: 0; padding: 24px 20px; background: rgba(26,18,13,.82); border-left: 1px solid var(--line); border-right: 0; backdrop-filter: blur(7px); }
  h2 { font-size: clamp(34px, 10vw, 46px); }
  .evidence { gap: 12px; }
  .resolution { min-height: 118svh; padding: 14svh 16px 15svh; }
  .final-copy { width: 100%; padding: 34px 20px; }
  .final-copy h2 { font-size: clamp(38px, 10vw, 50px); }
  .primary-action { width: 100%; min-height: 58px; font-size: 14px; }
  footer { left: 20px; right: 20px; gap: 12px; font-size: 9px; }
}

